cat > "$SP/verify-eng-2114.mjs" <<'EOF'
import { connect } from "./cdp.mjs";

const SCRATCH = "__eng2114-scratch.md";
const results = [];
const check = (label, pass, detail = "") => {
  results.push({ label, pass, detail });
  console.log(`${pass ? "PASS" : "FAIL"}  ${label}${detail ? ` — ${detail}` : ""}`);
};

const json = (v) => JSON.stringify(v);

const client = await connect();
console.log("connected to vault target");
await client.reloadPlugin();
await client.waitFor(`!!app.plugins.plugins["@discourse-graph/obsidian"]`, {
  label: "plugin re-enabled",
});

// Baseline: one clean tab holding the scratch note, no stray modals.
const savedConfig = await client.evaluate(`return {
  useMarkdownLinks: app.vault.getConfig("useMarkdownLinks"),
  newLinkFormat: app.vault.getConfig("newLinkFormat"),
};`);
console.log("saved vault link config:", savedConfig);

const firstNodeTitle = await client.evaluate(`
  const nodes = app.plugins.plugins["@discourse-graph/obsidian"].settings.nodeTypes;
  const files = app.vault.getMarkdownFiles().filter((f) => f.path !== ${json(SCRATCH)});
  const match = files.find((f) => nodes.some((n) => f.basename.startsWith(n.format.replace("{content}", "").trim())));
  return (match ?? files[0]).basename;
`);
console.log("target node:", firstNodeTitle);

const openScratchAt = async (body, line, ch) => {
  await client.evaluate(`
    return (async () => {
      const existing = app.vault.getAbstractFileByPath(${json(SCRATCH)});
      if (existing) await app.vault.modify(existing, ${json(body)});
      else await app.vault.create(${json(SCRATCH)}, ${json(body)});
      const file = app.vault.getAbstractFileByPath(${json(SCRATCH)});
      app.workspace.detachLeavesOfType("markdown");
      const leaf = app.workspace.getLeaf(true);
      await leaf.openFile(file, { state: { mode: "source" } });
      app.workspace.setActiveLeaf(leaf, { focus: true });
      const view = app.workspace.getActiveViewOfType(obsidian_MarkdownView_placeholder);
      return true;
    })();
  `.replace("obsidian_MarkdownView_placeholder", "app.workspace.activeLeaf.view.constructor"));
  await client.evaluate(`
    const view = app.workspace.activeLeaf.view;
    view.editor.focus();
    view.editor.setCursor({ line: ${line}, ch: ${ch} });
    return true;
  `);
};

const openSearch = async () => {
  await client.evaluate(
    `return app.commands.executeCommandById("@discourse-graph/obsidian:open-node-search");`,
  );
  await client.waitFor(`!!document.querySelector(".dg-node-search-modal")`, {
    label: "search modal open",
  });
};

const footerLabels = () =>
  client.evaluate(`
    return Array.from(
      document.querySelectorAll(".dg-node-search-modal .dg-search-footer-action"),
    ).map((el) => el.textContent.trim());
  `);

const typeQuery = async (text) => {
  await client.evaluate(`
    const input = document.querySelector(".dg-node-search-modal input");
    input.focus();
    return true;
  `);
  for (const char of text) {
    await client.key({ type: "keyDown", text: char, key: char });
  }
  // Beat the 250ms search debounce.
  await client.waitFor(
    `document.querySelectorAll('.dg-node-search-modal [role="option"]').length > 0`,
    { label: "results rendered", timeout: 4000 },
  );
};

const pressModEnter = () =>
  client.key({
    type: "keyDown",
    key: "Enter",
    code: "Enter",
    windowsVirtualKeyCode: 13,
    nativeVirtualKeyCode: 13,
    modifiers: 4, // Meta
  });

const readScratch = () =>
  client.evaluate(
    `return app.vault.read(app.vault.getAbstractFileByPath(${json(SCRATCH)}));`,
  );

const closeModalIfOpen = async () => {
  await client.evaluate(`
    const modal = document.querySelector(".dg-node-search-modal");
    if (modal) app.workspace.trigger("nothing");
    return true;
  `);
  await client.key({ type: "keyDown", key: "Escape", code: "Escape", windowsVirtualKeyCode: 27, nativeVirtualKeyCode: 27 });
};

// ---------------------------------------------------------------- scenario 1
// Link lands at the pre-open cursor, mid-line, in the right note.
const runInsertScenario = async ({ label, useMarkdownLinks, newLinkFormat }) => {
  await client.evaluate(`
    app.vault.setConfig("useMarkdownLinks", ${json(useMarkdownLinks)});
    app.vault.setConfig("newLinkFormat", ${json(newLinkFormat)});
    return true;
  `);
  await openScratchAt("before| after\n", 0, 6);
  await openSearch();

  const labels = await footerLabels();
  check(
    `${label}: insert action present in footer`,
    labels.some((l) => l.includes("insert link at cursor")),
    labels.join(" / "),
  );

  await typeQuery(firstNodeTitle.slice(0, 4));
  const chosen = await client.evaluate(`
    const row = document.querySelector('.dg-node-search-modal [aria-selected="true"]');
    return row ? row.textContent.trim() : null;
  `);
  await pressModEnter();

  await client.waitFor(`!document.querySelector(".dg-node-search-modal")`, {
    label: "modal closed after insert",
  });
  check(`${label}: modal closed after insert`, true);

  await client.waitFor(
    `app.vault.read(app.vault.getAbstractFileByPath(${json(SCRATCH)})).then((t) => t !== "before| after\\n")`,
    { label: "scratch note written" },
  );
  const text = await readScratch();
  const inserted = text.replace("before", "").replace(" after\n", "").replace("|", "");
  check(
    `${label}: link landed at pre-open cursor (col 6)`,
    text.startsWith("before") && text.endsWith(" after\n") && text !== "before| after\n",
    JSON.stringify(text),
  );
  const isMarkdownLink = /^\[[^\]]*\]\([^)]*\)$/.test(inserted.replace("|", "").trim());
  const isWikilink = /^\[\[.*\]\]$/.test(inserted.replace("|", "").trim());
  check(
    `${label}: format is ${useMarkdownLinks ? "markdown" : "wikilink"}`,
    useMarkdownLinks ? isMarkdownLink : isWikilink,
    inserted.trim(),
  );

  const focus = await client.evaluate(`
    const view = app.workspace.getActiveViewOfType(app.workspace.activeLeaf.view.constructor);
    const editor = app.workspace.activeLeaf.view.editor;
    return {
      hasFocus: editor.hasFocus(),
      cursor: editor.getCursor(),
      path: app.workspace.activeLeaf.view.file.path,
    };
  `);
  check(
    `${label}: focus returned to the editor`,
    focus.hasFocus === true,
    JSON.stringify(focus),
  );
  check(
    `${label}: cursor sits after the inserted link`,
    focus.cursor.line === 0 && focus.cursor.ch > 6,
    `ch=${focus.cursor.ch}`,
  );
  check(
    `${label}: inserted into the pre-open note`,
    focus.path === SCRATCH,
    focus.path,
  );
  console.log(`   chosen row: ${chosen}`);
};

await runInsertScenario({
  label: "wikilink/shortest",
  useMarkdownLinks: false,
  newLinkFormat: "shortest",
});
await runInsertScenario({
  label: "markdown/absolute",
  useMarkdownLinks: true,
  newLinkFormat: "absolute",
});

// ---------------------------------------------------------------- scenario 2
// Selection is replaced rather than orphaned.
await client.evaluate(`
  app.vault.setConfig("useMarkdownLinks", false);
  app.vault.setConfig("newLinkFormat", "shortest");
  return true;
`);
await openScratchAt("replace THIS please\n", 0, 0);
await client.evaluate(`
  const editor = app.workspace.activeLeaf.view.editor;
  editor.setSelection({ line: 0, ch: 8 }, { line: 0, ch: 12 });
  return true;
`);
await openSearch();
await typeQuery(firstNodeTitle.slice(0, 4));
await pressModEnter();
await client.waitFor(`!document.querySelector(".dg-node-search-modal")`, {
  label: "modal closed (selection case)",
});
const selectionText = await readScratch();
check(
  "selection is replaced by the link",
  selectionText.startsWith("replace ") &&
    selectionText.endsWith(" please\n") &&
    !selectionText.includes("THIS"),
  JSON.stringify(selectionText),
);

// ---------------------------------------------------------------- scenario 3
// Reading mode has no cursor: the action must be absent.
await openScratchAt("reading mode\n", 0, 0);
await client.evaluate(`
  return app.workspace.activeLeaf.setViewState({
    type: "markdown",
    state: { file: ${json(SCRATCH)}, mode: "preview" },
  }).then(() => true);
`);
await client.waitFor(`app.workspace.activeLeaf.view.getMode() === "preview"`, {
  label: "reading mode active",
});
await openSearch();
const readingLabels = await footerLabels();
check(
  "insert action absent in reading mode",
  !readingLabels.some((l) => l.includes("insert link at cursor")),
  readingLabels.join(" / "),
);
await closeModalIfOpen();
await client.waitFor(`!document.querySelector(".dg-node-search-modal")`, {
  label: "modal closed (reading mode)",
});

// ---------------------------------------------------------------- scenario 4
// No markdown view at all: the action must be absent.
await client.evaluate(`
  app.workspace.detachLeavesOfType("markdown");
  return true;
`);
await openSearch();
const emptyLabels = await footerLabels();
check(
  "insert action absent with no note open",
  !emptyLabels.some((l) => l.includes("insert link at cursor")),
  emptyLabels.join(" / "),
);
await closeModalIfOpen();

// ---------------------------------------------------------------- teardown
await client.evaluate(`
  app.vault.setConfig("useMarkdownLinks", ${json(savedConfig.useMarkdownLinks)});
  app.vault.setConfig("newLinkFormat", ${json(savedConfig.newLinkFormat)});
  const scratch = app.vault.getAbstractFileByPath(${json(SCRATCH)});
  return (scratch ? app.vault.trash(scratch, true) : Promise.resolve()).then(() => true);
`);
console.log("restored vault link config, trashed scratch note");

const failed = results.filter((r) => !r.pass);
console.log(`\n${results.length - failed.length}/${results.length} assertions passed`);
client.close();
process.exit(failed.length ? 1 : 0);
EOF
echo "harness written"; ls -la "$SP"

